// Wraps the OpenNext worker so Cloudflare's daily cron can call the existing /api/cron/expire-pro route.
// @ts-ignore `.open-next/worker.js` is generated by `opennextjs-cloudflare build`
import handler from "./.open-next/worker.js";

export default {
	fetch: handler.fetch,

	async scheduled(_event: unknown, env: any, ctx: { waitUntil(p: Promise<unknown>): void }) {
		if (!env.CRON_SECRET) return; // the route would answer 401 anyway
		ctx.waitUntil(
			env.WORKER_SELF_REFERENCE.fetch("https://self.invalid/api/cron/expire-pro", {
				headers: { authorization: `Bearer ${env.CRON_SECRET}` },
			}),
		);
	},
} satisfies ExportedHandler<any>;

// @ts-ignore re-exported because OpenNext declares these classes in its worker
export { DOQueueHandler, DOShardedTagCache, BucketCachePurge } from "./.open-next/worker.js";
